<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'
import { api, rows, keyOf, pretty, terminal, type Row } from './api'
import JsonView from './JsonView.vue'
const error = ref(''), busy = ref(false), datasets = ref<Row[]>([]), snapshots = ref<Row[]>([]), configs = ref<Row[]>([]), datasetId = ref(''), versionId = ref(''), cases = ref<Row[]>([]), snapshotId = ref(''), configId = ref(''), repeats = ref(1), result = ref<any>(null), runId = ref(''), results = ref<Row[]>([]), comparisonIds = ref(''), selected = ref<any>(null), selectedOpen = ref(false), editorOpen = ref(false), editor = ref(''), editorTitle = ref(''), editorPath = ref(''), editorMethod = ref('POST'), estimate = ref<Row | null>(null), imported = ref('')
let timer: ReturnType<typeof setTimeout> | undefined, disposed = false
// 默认 HUMAN：避免用户仅仅打开页面/启动实验就产生 Judge 模型费用。
const judgeMode = ref('HUMAN')
async function act(fn: () => Promise<void>) { error.value = ''; busy.value = true; try { await fn() } catch (e) { error.value = String(e) } finally { busy.value = false } }
async function load() { datasets.value = rows(await api('/admin/eval/datasets')); snapshots.value = rows(await api('/admin/eval/snapshots')); configs.value = rows(await api('/admin/configs')) }
function edit(title: string, path: string, body: unknown, method = 'POST') { editorTitle.value = title; editorPath.value = path; editorMethod.value = method; editor.value = pretty(body); editorOpen.value = true }
async function save() { await act(async () => { result.value = await api(editorPath.value, editorMethod.value, JSON.parse(editor.value)); editorOpen.value = false; await load(); if (versionId.value) await loadCases() }) }
async function loadCases() { cases.value = rows(await api(`/admin/eval/dataset-versions/${versionId.value}/cases`)) }
async function freeze() { await act(async () => { result.value = await api(`/admin/eval/dataset-versions/${versionId.value}/freeze`, 'POST'); await loadCases() }) }
// estimate 和 start 必须使用同一组参数；后端通过 estimateId 检测两步之间是否发生变化。
function runBody() { return { datasetVersionId: versionId.value, snapshotId: snapshotId.value, configId: configId.value, repeats: repeats.value, judgeMode: judgeMode.value } }
async function estimateRun() { await act(async () => { estimate.value = await api('/admin/eval/estimates', 'POST', runBody()); result.value = estimate.value }) }
// 强制“先估算再启动”，避免绕过费用确认直接触发真实模型评估。
async function start() { await act(async () => { if (!estimate.value) throw new Error('先估算费用，检查题集、快照和配置后再运行'); result.value = await api('/admin/eval/runs', 'POST', { ...runBody(), maxCostCny: 10, estimateId: estimate.value.estimateId || estimate.value.id }); runId.value = result.value.runId || result.value.id; estimate.value = null; poll() }) }
// 同时刷新 run 汇总和逐题结果；终态后停止轮询。
async function poll() { if (!runId.value || disposed) return; try { result.value = await api('/admin/eval/runs/' + runId.value); results.value = rows(await api(`/admin/eval/runs/${runId.value}/results`)); if (!terminal(result.value.status)) timer = setTimeout(poll, document.hidden ? 5000 : 1500) } catch (e) { error.value = String(e) } }
async function importCases() { await act(async () => { const parsed = imported.value.trim().split(/\r?\n/).filter(Boolean).map(line => JSON.parse(line)); result.value = await api(`/admin/eval/dataset-versions/${versionId.value}/cases`, 'POST', { cases: parsed }); imported.value = ''; await loadCases() }) }
// effectiveJudgment 已由后端按“人工最新值优先，否则自动值”合并，前端不重复实现规则。
function effective(row: Row, dimension: string) { return row.effectiveJudgment?.[dimension] ?? '未评估' }
// labels 默认空对象：只提交用户明确修改的维度，避免把其他人工标签误覆盖成 UNKNOWN。
function review(row: Row) {
  edit(
    '人工复核（只提交明确修改的维度）',
    '/admin/eval/results/' + keyOf(row) + '/reviews',
    { labels: {}, reason: '' },
  )
}
onMounted(() => act(load)); onUnmounted(() => { disposed = true; clearTimeout(timer) })
</script>
<template><section><h2>实验评估</h2><label>答案评分方式</label><el-select v-model="judgeMode" aria-label="答案评分方式" @change="estimate = null"><el-option value="HUMAN" label="人工复核" /><el-option value="LLM" label="模型逐事实评分（需要模型服务）" /></el-select><p class="muted">使用隔离评测环境与已批准模拟资料。费用先估算，冻结后修改请创建新版本。运行身份与查看权限由服务端检查。</p><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-tabs><el-tab-pane label="题集与标注"><div class="toolbar"><el-select v-model="datasetId" placeholder="题集版本" @change="versionId = datasetId; estimate = null; act(loadCases)"><el-option v-for="d in datasets" :key="keyOf(d)" :value="keyOf(d)" :label="d.name + ' · v' + d.revision + ' · ' + d.status" /></el-select><el-button @click="edit('创建题集', '/admin/eval/datasets', {name: '', description: ''})">创建题集</el-button><el-button :disabled="!datasetId" @click="edit('创建题集版本', '/admin/eval/datasets/' + datasetId + '/versions', {sourceVersionId: versionId || null})">创建 / 复制版本</el-button><el-button @click="act(load)">刷新</el-button></div><el-collapse><el-collapse-item title="题集版本清单"><JsonView :value="datasets.find(d => keyOf(d) === datasetId) || datasets" /></el-collapse-item></el-collapse><div class="toolbar"><el-input v-model="versionId" placeholder="题集版本 ID（从清单复制）" @input="estimate = null" /><el-button :disabled="!versionId" @click="act(loadCases)">读取题目</el-button><el-button :disabled="!versionId" @click="edit('新建题目与标准证据', '/admin/eval/dataset-versions/' + versionId + '/cases', {caseKey: '', groupKey: '', category: 'FACT', question: {text: ''}, split: 'DEV', persona: {loginName: 'operator'}, expected: {status: 'ANSWER', answerPoints: [], evidenceGroups: []}, annotationStatus: 'DRAFT'})">添加题目</el-button><el-button :disabled="!versionId" type="warning" @click="freeze">校验并冻结</el-button></div><el-table :data="cases" empty-text="选择版本后读取题目"><el-table-column label="问题" min-width="220"><template #default="{row}">{{ typeof row.question === 'string' ? row.question : row.question?.text }}</template></el-table-column><el-table-column prop="split" label="划分" width="90" /><el-table-column prop="annotationStatus" label="标注" width="120" /><el-table-column label="操作" width="230"><template #default="{row}"><el-button size="small" @click="edit('编辑草稿标注', '/admin/eval/cases/' + keyOf(row), row, 'PATCH')">标注</el-button><el-button size="small" @click="act(async () => { await api('/admin/eval/cases/' + keyOf(row), 'DELETE'); await loadCases() })">删除草稿</el-button><el-button size="small" @click="selected = row; selectedOpen = true">详情</el-button></template></el-table-column></el-table><el-collapse><el-collapse-item title="批量导入 JSONL（一行一题）"><el-input v-model="imported" type="textarea" :rows="6" aria-label="JSONL 题目" /><el-button :disabled="!versionId || !imported.trim()" @click="importCases">导入到草稿版本</el-button></el-collapse-item></el-collapse></el-tab-pane><el-tab-pane label="快照与运行"><div class="toolbar"><el-button @click="edit('冻结已批准语料快照', '/admin/eval/snapshots', {name: '', documentIds: [], approvedSyntheticOrRedacted: true})">新建快照</el-button><el-button @click="act(load)">刷新快照和配置</el-button></div><div class="toolbar"><el-input v-model="versionId" placeholder="冻结题集版本 ID" @input="estimate = null" /><el-select v-model="snapshotId" placeholder="语料快照" @change="estimate = null"><el-option v-for="s in snapshots" :key="keyOf(s)" :value="keyOf(s)" :label="s.name || keyOf(s)" /></el-select><el-select v-model="configId" placeholder="策略配置" @change="estimate = null"><el-option v-for="c in configs" :key="keyOf(c)" :value="keyOf(c)" :label="c.name || keyOf(c)" /></el-select><el-input-number v-model="repeats" :min="1" :max="10" @change="estimate = null" /><el-button :disabled="!versionId || !snapshotId || !configId" @click="estimateRun">估算费用</el-button><el-button type="primary" :disabled="!estimate" @click="start">按估算启动</el-button></div><div class="toolbar"><el-input v-model="runId" placeholder="评估运行 ID" /><el-button :disabled="!runId" @click="act(poll)">读取 / 跟踪运行</el-button><el-button :disabled="!runId" @click="act(async () => { await api('/admin/eval/runs/' + runId + '/cancel', 'POST'); await poll() })">取消</el-button><el-button :disabled="!runId" @click="act(async () => { result = await api('/admin/eval/runs/' + runId + '/exports', 'POST', {mode: 'REDACTED'}) })">脱敏导出</el-button></div><el-table :data="results" empty-text="运行后显示全部逐题结果，包括失败题"><el-table-column label="问题" min-width="220"><template #default="{row}">{{ typeof row.question === 'string' ? row.question : row.question?.text }}</template></el-table-column><el-table-column prop="status" label="执行状态" width="110" /><el-table-column label="Correctness" width="130"><template #default="{row}">{{ effective(row, 'correctness') }}</template></el-table-column><el-table-column label="Answer Relevancy" width="150"><template #default="{row}">{{ effective(row, 'answerRelevance') }}</template></el-table-column><el-table-column label="诊断 / 复核" width="220"><template #default="{row}"><el-button size="small" @click="selected = row; selectedOpen = true">逐题详情</el-button><el-button size="small" @click="review(row)">人工复核</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="配对对照"><p>输入逗号分隔的运行 ID；服务端核对 manifest，不能比较的运行会明确返回原因。</p><div class="toolbar"><el-input v-model="comparisonIds" placeholder="runId1,runId2" /><el-button :disabled="!comparisonIds" @click="act(async () => { result = await api('/admin/eval/comparisons?runIds=' + encodeURIComponent(comparisonIds)) })">比较</el-button></div></el-tab-pane></el-tabs><div v-if="result?.metrics"><h3>评估摘要</h3><p class="muted">范围：{{ result.manifest?.evaluationScope || '历史运行未记录' }}；Relevancy 策略：{{ result.manifest?.relevancePolicy || '未评估' }}。taskSuccessRate 是已判定样本成功率，plannedTaskSuccessRate 是成功数 / 全计划数。</p><div class="toolbar"><span>计划 {{ result.metrics.planned }}</span><span>完成 {{ result.metrics.completed }}</span><span>执行失败 {{ result.metrics.executionFailed ?? result.metrics.failed }}</span><span>未知 {{ result.metrics.unknown ?? '—' }}</span><span>已判定成功率 {{ result.metrics.taskSuccessRate ?? '—' }}</span><span>全计划成功率 {{ result.metrics.plannedTaskSuccessRate ?? '—' }}</span><span>Relevancy 覆盖率 {{ result.metrics.answerRelevance?.coverage ?? '—' }}</span></div></div><h2 v-if="result">最近操作结果</h2><JsonView v-if="result" :value="result" /><el-dialog v-model="editorOpen" :title="editorTitle" width="800px"><p class="muted">JSON 字段由后端校验；证据使用实际文档版本和原文位置，不能填入编造 ID。</p><el-input v-model="editor" type="textarea" :rows="17" aria-label="编辑 JSON" /><template #footer><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="selectedOpen" title="逐题候选、证据、指标与人工标签" width="900px"><JsonView :value="selected" /></el-dialog></section></template>
